import { Youtube, Instagram, Mail } from 'lucide-react';
import { CHANNEL_URL } from '@/data/films';

const socials = [
  { icon: Youtube, label: 'YouTube', href: CHANNEL_URL },
  { icon: Instagram, label: 'Instagram', href: CHANNEL_URL },
  { icon: Mail, label: 'Email', href: 'mailto:sri20srini09@gmail.com' },
];

export const Footer = () => {
  return (
    <footer className="relative border-t border-white/10 bg-[#0a0a0a] px-6 md:px-12 pt-20 pb-10 overflow-hidden">
      <div className="flex flex-col lg:flex-row justify-between gap-12">
        <div>
          <div className="flex items-center gap-2 mb-6">
            <span className="inline-block w-2 h-2 bg-[#E11D48]" />
            <span className="font-display font-semibold text-sm tracking-[0.25em] uppercase">
              Stupid Studios
            </span>
          </div>
          <p className="text-white/50 max-w-sm leading-relaxed text-sm">
            An independent Tamil short-film collective. Subscribe on YouTube to catch every new
            release first.
          </p>
        </div>

        <div className="flex flex-col gap-4">
          <span className="text-[11px] tracking-[0.2em] uppercase text-white/40">Follow</span>
          {socials.map((s) => {
            const Icon = s.icon;
            return (
              <a
                key={s.label}
                href={s.href}
                target="_blank"
                rel="noopener noreferrer"
                data-testid={`footer-social-${s.label.toLowerCase()}`}
                className="group flex items-center gap-3 text-white/70 hover:text-white transition-colors duration-300"
              >
                <Icon className="w-5 h-5 group-hover:text-[#E11D48] transition-colors duration-300" strokeWidth={1.5} />
                <span className="text-sm tracking-wide">{s.label}</span>
              </a>
            );
          })}
        </div>
      </div>

      <div className="mt-16 -mb-4">
        <h2 className="font-display font-semibold text-[18vw] leading-[0.8] uppercase text-white/[0.06] select-none">
          Stupid Studios
        </h2>
      </div>

      <div className="mt-8 flex flex-col sm:flex-row justify-between gap-3 text-[11px] tracking-[0.15em] uppercase text-white/30">
        <span>© {new Date().getFullYear()} Stupid Studios. All rights reserved.</span>
        <span>Crafted frame by frame.</span>
      </div>
    </footer>
  );
};
